<?php
function om_form($action,$extra=[],$upload=false){echo '<form method="post" action="order_monitor_action.php"'.($upload?' enctype="multipart/form-data"':'').'><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'">';foreach($extra as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function om_impact_panel($plan){$changes=[];foreach($plan['orders'] as $r){if($r['errors'])continue;foreach($r['totals'] as $pid=>$qty){if(!isset($changes[$pid]))$changes[$pid]=['reserve'=>0,'dispatch'=>0,'release'=>0];if($r['action']==='Reserve')$changes[$pid]['reserve']+=$qty;if($r['action']==='Dispatch / post')$changes[$pid]['dispatch']+=$qty;if($r['action']==='Cancel / release')$changes[$pid]['release']+=(int)om_query('SELECT qty FROM om_reservations WHERE order_id=? AND product_id=?',[$r['order_record']['id'],$pid])->fetchColumn();}}
 $rows=[];foreach($changes as $pid=>$c){if(!array_sum($c))continue;$s=stock_row($pid);$held=om_reserved($pid);$after=$s['current']-$c['dispatch'];$reserved=$held+$c['reserve']-$c['dispatch']-$c['release'];$rows[]=[$s['master_sku'].' / '.$s['name'],$s['current'].' → '.$after,$held.' → '.$reserved,($s['current']-$held).' → '.($after-$reserved),$s['physical'].' → '.($s['physical']-$c['dispatch'])];}if($rows){echo '<div class="card"><h3>Projected Inventory Effect</h3>';om_table(['Product','Sellable Before → After','Reserved Before → After','Available Before → After','Physical Before → After'],$rows);echo '<p class="muted">Registration and reservation release do not change physical stock. Only confirmed dispatches deduct physical stock.</p></div>';}}
function om_select($name,$label,$values,$selected='',$all=false){echo '<label>'.e($label).'<select name="'.e($name).'">';if($all)echo '<option value="">All</option>';foreach($values as $k=>$v){if(is_int($k))$k=$v;echo '<option value="'.e($k).'"'.((string)$selected===(string)$k?' selected':'').'>'.e($v).'</option>';}echo '</select></label>';}
function om_table($heads,$rows,$links=[]){echo '<div class="om-table"><table class="table"><thead><tr>';foreach($heads as $h)echo '<th>'.e($h).'</th>';if($links)echo '<th>Action</th>';echo '</tr></thead><tbody>';foreach($rows as $i=>$r){echo '<tr>';foreach($r as $v)echo '<td>'.e($v).'</td>';if($links)echo '<td>'.($links[$i]??'').'</td>';echo '</tr>';}if(!$rows)echo '<tr><td colspan="'.(count($heads)+($links?1:0)).'">No matching records.</td></tr>';echo '</tbody></table></div>';}
function om_export_links($input,$label='Download Excel'){echo '<div class="om-actions"><a class="btn secondary" href="order_monitor_action.php?'.e(http_build_query($input+['download'=>'report','format'=>'xlsx'])).'">'.e($label).'</a><a class="btn ghost" target="_blank" href="order_monitor_action.php?'.e(http_build_query($input+['download'=>'report','format'=>'print'])).'">Print / PDF</a></div>';}
function om_page(){echo '<link rel="stylesheet" href="assets/order_monitor.css?v=5.9.2"><div class="om-wrap">';if(!om_ready()){echo '<div class="alert warn">Ask Admin to complete the Order Monitoring upgrade.</div></div>';return;}$view=$_GET['view']??'monitor';$order=(int)($_GET['order_id']??0);echo '<div class="page-head"><div><h1>Order Monitoring</h1><p>Track order statuses, manual releases and inventory posting history.</p></div><div class="om-actions"><a class="btn ghost" href="?page=order_monitor">Monitoring</a><a class="btn ghost" href="?page=order_monitor&view=reports">Reports</a>'.(om_allowed()?'<a class="btn ghost" href="?page=order_monitor&view=settings">Alert Settings</a>':'').'</div></div>';try{if($order)om_order_page($order);elseif($view==='settings')om_settings_page();elseif($view==='reports')om_monitor_page(true);else gm_page();}catch(Throwable $ex){echo '<div class="alert danger">'.e(safe_error_message($ex)).'</div>';}echo '</div>';}
function om_entry_page($kind){os_entry_page($kind);}
function om_upload_page($id){os_upload_page($id);}
function om_order_list($input){$all=om_filtered_orders($input);$size=rs8_page_size('order_monitor');$offset=max(0,(int)($_GET['om_offset']??0));$offset=min($offset,max(0,(int)floor(max(0,count($all)-1)/$size)*$size));$rows=[];$links=[];$cfg=om_alert_settings();foreach(array_slice($all,$offset,$size) as $o){$age=max(0,(int)((strtotime(date('Y-m-d'))-strtotime($o['fulfillment_date']))/86400));$r=(int)om_query('SELECT COALESCE(SUM(qty),0) FROM om_reservations WHERE order_id=?',[$o['id']])->fetchColumn();$rows[]=[$o['order_no'],$o['platform'].' / '.$o['shop'],$o['fulfillment_date'],$o['platform_status'].' / '.$o['posting'],$o['monitoring'],$r,$o['monitoring']!=='Resolved'&&$age>=$cfg['high_days']?'HIGH · '.$age.' days':$age.' days',$o['last_seen_at']??'Never checked',$o['owner_name'],$o['exception_text']];$links[]='<a class="btn ghost sm" href="?page=order_monitor&order_id='.$o['id'].'">View</a>';}om_table(['Order ID','Platform / Shop','Registered','Status / Posting','Monitoring','Reserved','Age','Last Seen','Responsible','Exception'],$rows,$links);echo rs8_pagination(count($all),$offset,$size,$_GET,'om_offset');}
function om_monitor_page($reports=false){$input=$_GET;$input['report_view']=$input['report_view']??'open';echo '<div class="card"><form method="get"><input type="hidden" name="page" value="order_monitor"><input type="hidden" name="view" value="'.($reports?'reports':'monitor').'"><div class="om-grid">';om_select('report_view','View',['all'=>'All Orders','dispatch'=>'Open for Dispatch','delivery'=>'Open for Delivery','open'=>'Open Orders & Aging','returns'=>'Return Follow-up','exceptions'=>'Posting / Status Exceptions','readiness'=>'Inventory Readiness','history'=>'Status & Action History','uploads'=>'Upload History','reservations'=>'Reservation Activity','source_exceptions'=>'Unregistered Dispatch Exceptions'],$input['report_view']??'open');om_select('platform','Platform',['Shopee','Lazada','TikTok'],$input['platform']??'',true);om_select('platform_status','Platform Status',['To Ship','Shipped','Delivered','Completed','Cancelled','Unpaid','Needs Checking','Return / Refund'],$input['platform_status']??'',true);om_select('posting','Inventory Posting',['Not Posted','Posted','Reversed'],$input['posting']??'',true);om_select('monitoring','Monitoring',['Needs Follow-up','Missing','Carried Over','Resolved'],$input['monitoring']??'',true);om_select('age','Pending Age',['high'=>'High alert only'],$input['age']??'',true);echo '<label>Registered From<input type="date" name="from" value="'.e($input['from']??'').'"></label><label>Registered Through<input type="date" name="to" value="'.e($input['to']??'').'"></label><label>Order ID<input name="q" placeholder="Search order number" value="'.e($input['q']??'').'"></label>'; $users=[];foreach(db()->query('SELECT id,name FROM users ORDER BY name') as $u)$users[$u['id']]=$u['name'];om_select('owner_id','Responsible User',$users,$input['owner_id']??'',true);echo '</div><div class="om-actions"><a class="btn ghost" href="?page=order_monitor&view='.($reports?'reports':'monitor').'">Clear Filters</a><button class="btn primary">Generate Report / Apply Filters</button></div></form></div><div class="card">';om_export_links($input);$v=$input['report_view']??'open';if(in_array($v,['readiness','history','uploads','reservations','source_exceptions'],true)){$r=om_report($input);$sz=rs8_page_size('order_monitor');$off=max(0,(int)($_GET['om_offset']??0));om_table($r['headers'],array_slice($r['rows'],$off,$sz));echo rs8_pagination(count($r['rows']),$off,$sz,$_GET,'om_offset');}else om_order_list($input);echo '<div class="om-note">Read or dismissed notification does not resolve an order. Pending age is not reset by another To Ship export. Inventory readiness is a review checklist; count reserved items still physically held in the warehouse.</div></div>';}
function om_history_page(){echo '<div class="card"><h3>Upload History</h3>';$all=om_query('SELECT b.*,u.name uploader FROM om_uploads b LEFT JOIN users u ON u.id=b.created_by WHERE b.platform=? ORDER BY b.id DESC',[gm_platform($_GET)])->fetchAll();$size=rs8_page_size('order_monitor');$offset=max(0,(int)($_GET['om_offset']??0));$rows=[];$links=[];foreach(array_slice($all,$offset,$size) as $b){$rows[]=[$b['id'],$b['created_at'],$b['platform'].' / '.$b['shop'],$b['kind'],$b['filename'],$b['status'],$b['uploader']];$links[]='<a class="btn ghost sm" href="?page=outflow&upload_id='.$b['id'].'">View / Review</a>';}om_table(['Upload','Date','Platform / Shop','Type','File','Status','Uploader'],$rows,$links);echo rs8_pagination(count($all),$offset,$size,$_GET,'om_offset').'</div>';}
function om_order_page($id){$o=om_order($id);echo '<div class="card"><h3>'.e($o['order_no']).'</h3><p>'.e($o['platform'].' / '.$o['shop']).'</p><div class="om-summary">';foreach(['Platform Status'=>$o['platform_status'],'Inventory Posting'=>$o['posting'],'Monitoring'=>$o['monitoring'],'After-sales'=>$o['aftersales']?:'None'] as $k=>$v)echo '<div><span>'.e($k).'</span><b>'.e($v).'</b></div>';echo '</div><p>Registered: '.e($o['fulfillment_date']).' · Last verified: '.e($o['last_seen_at']??'Never').' · Next follow-up: '.e($o['followup_date']??'Not set').'</p>';if($o['exception_text'])echo '<div class="alert warn">'.e($o['exception_text']).'</div>';echo '</div><div class="card"><h3>Products & Reservations</h3>';$rows=[];$links=[];foreach(om_query('SELECT r.*,p.master_sku,p.name FROM om_reservations r JOIN products p ON p.id=r.product_id WHERE r.order_id=?',[$id]) as $r){$s=stock_row($r['product_id']);$rows[]=[$r['master_sku'],$r['name'],$r['qty'],$s['current'],om_reserved($r['product_id']),om_available($r['product_id']),$s['physical']];$links[]='<a class="btn ghost sm" href="?page=product_detail&id='.$r['product_id'].'&include_reservations=1">Stock Movements</a>';}om_table(['Master SKU','Product','Reserved for Order','Sellable On Hand','Total Reserved','Available','Physical'],$rows,$links);echo '</div><div class="card"><h3>Linked Posted Outflows / Returns</h3>';$rows=[];$links=[];foreach(om_query('SELECT o.*,p.name FROM om_postings l JOIN outflows o ON o.id=l.outflow_id JOIN products p ON p.id=o.product_id WHERE l.order_id=?',[$id]) as $r){$rows[]=[$r['txn_date'],$r['name'],$r['qty'],$r['reversed_by_request']?'Reversed':'Posted'];$links[]='<a class="btn ghost sm" href="?page=outflow_batch&id='.(int)$r['import_batch_id'].'">Original Outflow</a>';}om_table(['Date','Product','Quantity','Posting'],$rows,$links);foreach(om_query('SELECT DISTINCT b.id,b.batch_ref FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id WHERE r.platform=? AND r.original_ref=? AND r.reversed=0',[$o['platform'],$o['order_no']]) as $ret)echo '<a class="btn ghost" href="?page=manual_receiving&id='.$ret['id'].'">'.e($ret['batch_ref']).'</a>';echo '</div>';
 if(can_action('return_confirm')&&$o['posting']==='Posted'){om_form('om_receive',['order_id'=>$id]);echo '<div class="card"><p>Use actual receiving only when the items physically return. Existing receipts are listed above.</p><button class="btn secondary">Open Return Order with These Items</button></div></form>';}
 if(om_allowed()){
 echo '<div class="card"><h3>Follow-up / Reassign</h3>';om_form('om_followup',['order_id'=>$id]);echo '<div class="om-grid"><label>Reason<input name="reason" minlength="3" required></label><label>Next Follow-up<input type="date" name="followup_date" min="'.date('Y-m-d').'" value="'.date('Y-m-d',strtotime('+1 day')).'" required></label>';$users=[];foreach(db()->query("SELECT id,name,role FROM users WHERE active=1 AND approval_status='Approved'") as $u)if(in_array(access_role_profile($u['role']),['Admin','Operations Lead'],true))$users[$u['id']]=$u['name'];om_select('owner_id','Responsible User',$users,$o['owner_id']);echo '</div><div class="om-actions"><button class="btn secondary">Save Follow-up</button></div></form></div>';
 if($o['aftersales']||$o['platform_status']==='Cancelled'){echo '<div class="card"><h3>Return / Refund Resolution</h3>';om_form('om_aftersales',['order_id'=>$id]);echo '<div class="om-grid">';om_select('outcome','Actual Outcome',['Return Expected','Refund Only','Receipt Linked'],$o['aftersales_resolution']);echo '<label class="wide">Reason / reference<input name="reason" minlength="3" required></label></div><button class="btn secondary">Save Resolution</button></form></div>';}
 if($o['platform_status']==='Cancelled'&&$o['posting']==='Posted'){echo '<div class="card"><h3>Cancelled After Posting</h3><p>If the complete order never left the warehouse, request a linked reversal. A different Admin must approve. If it left, use physical Return Order receiving instead.</p>';om_form('om_reversal',['order_id'=>$id]);echo '<label>Reason / evidence reference<input name="reason" minlength="3" required></label><label class="om-inline"><input type="checkbox" name="warehouse_ack" value="1" required> The complete order never left the warehouse and has no posted return receipt.</label><button class="btn secondary">Request Linked Reversal</button></form></div>';}
 }
 echo '<div class="card"><h3>Order History</h3>';foreach(om_query('SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.order_id=? ORDER BY e.id DESC',[$id]) as $r){echo '<div class="om-event"><b>'.e($r['event_type']).'</b><p>'.e($r['created_at'].' · '.($r['actor']?:'System')).'</p>';if($r['upload_id'])echo '<a href="?page=outflow&upload_id='.(int)$r['upload_id'].'">Source Upload #'.(int)$r['upload_id'].'</a>';echo '<details><summary>View Details</summary><pre>'.e(json_encode(json_decode($r['details_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre></details></div>';}echo '</div>';
}
function om_settings_page(){om_require();$s=om_alert_settings();echo '<div class="card om-settings"><h3>Reminders & High Alerts</h3><p>Operating days: Monday–Saturday. Pending age uses calendar days. Host computer must be on for scheduled checks.</p>';om_form('om_settings');echo '<div class="om-grid"><label>High alert after (calendar days)<input type="number" min="1" max="90" name="high_days" value="'.(int)$s['high_days'].'" required></label><label>Final upload reminder<input type="time" name="reminder" value="'.e($s['reminder']).'" required></label><label>Holiday / special date<input type="date" name="special_date"></label>';om_select('override','Operation on special date',['Operating','Closed']);echo '</div><div class="om-actions"><button class="btn primary">Save Settings</button></div></form><p>Current date overrides: '.e(json_encode($s['overrides'])).'</p><p class="muted">Install the supplied local reminder schedule once. Without it, alerts are refreshed when an authorized user opens Notifications or Order Monitoring. No marketplace API is needed.</p></div>';}
